B.atN=s(["\uc5b4\ub5a4 \ud55c\uc790\ub97c \uc5b8\uc81c \ub9de\ud614\ub294\uc9c0, \uba70\uce60 \uc5f0\uc18d\uc73c\ub85c \uacf5\ubd80\ud588\ub294\uc9c0 \uac19\uc740 \ud559\uc2b5 \uae30\ub85d\uc740 \uc571\uc744 \uc124\uce58\ud55c \uae30\uae30 \uc548\uc5d0\ub9cc \uc800\uc7a5\ub3fc\uc694.","\ud734\ub300\uc804\ud654\uc640 \ud0dc\ube14\ub9bf\ucc98\ub7fc \uae30\uae30\uac00 \uc5ec\ub7ec \ub300\uba74 \uae30\ub85d\uc740 \uc11c\ub85c \ub530\ub85c \uc313\uc5ec\uc694. \uae30\uae30\ub07c\ub9ac \uae30\ub85d\uc744 \ud569\uce58\ub294 \uae30\ub2a5\uc740 \uc544\uc9c1 \uc5c6\uc5b4\uc694.","\uc6f9 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \uc4f0\uba74 \uae30\ub85d\uc740 \uadf8 \ube0c\ub77c\uc6b0\uc800\uc758 \uc800\uc7a5 \uacf5\uac04\uc5d0 \ub0a8\uc544\uc694. \ube0c\ub77c\uc6b0\uc800 \uae30\ub85d\uc744 \uc9c0\uc6b0\uac70\ub098 \uc2dc\ud06c\ub9bf \ubaa8\ub4dc\ub85c \uc5f4\uba74 \ud559\uc2b5 \uae30\ub85d\ub3c4 \uc0ac\ub77c\uc9c8 \uc218 \uc788\uc5b4\uc694."],t.s)
B.aF4=new A.lh("2. \ud559\uc2b5 \uae30\ub85d\uc740 \uc5b4\ub514\uc5d0 \uc800\uc7a5\ub418\ub098\uc694",B.atN)
B.al_=s(['\uc815\ud574 \ub454 \uc2dc\uac04\uc5d0 "\uacf5\ubd80\ud560 \uc2dc\uac04\uc774\uc57c"\ub77c\uace0 \uc54c\ub824 \uc8fc\uae30 \uc704\ud574\uc11c\ub9cc \uc368\uc694. \uc2dc\ud5d8 \ub0a0\uc9dc\uac00 \ub2e4\uac00\uc624\uba74 \ub0a8\uc740 \ub0a0\uc744 \uc54c\ub824 \uc8fc\ub294 \ub370\uc5d0\ub3c4 \uc368\uc694.',"\uc54c\ub9bc\uc740 \uae30\uae30 \uc548\uc5d0\uc11c \ub9cc\ub4e4\uc5b4\uc838\uc694. \uc54c\ub9bc\uc744 \ub9cc\ub4e4\ub824\uace0 \uc678\ubd80 \uc11c\ubc84\uc5d0 \ubb34\uc5b8\uac00\ub97c \ubcf4\ub0b4\uc9c0 \uc54a\uc544\uc694.","\uc54c\ub9bc\uc744 \ubc1b\uace0 \uc2f6\uc9c0 \uc54a\uc73c\uba74 \uc124\uc815\uc5d0\uc11c \ub044\uac70\ub098, \uae30\uae30\uc758 \uc54c\ub9bc \uad8c\ud55c\uc744 \uaebc\ub3c4 \uc571\uc740 \uadf8\ub300\ub85c \uc4f8 \uc218 \uc788\uc5b4\uc694."],t.s)
B.aF3=new A.lh("3. \uc54c\ub9bc \uad8c\ud55c\uc740 \uc65c \ud544\uc694\ud55c\uac00\uc694",B.al_)
B.agp=s(["iPhone\uc758 iCloud \ubc31\uc5c5\uc774\ub098 Android\uc758 \uc790\ub3d9 \ubc31\uc5c5\uc744 \ucf1c \ub450\uba74, \uc6b4\uc601\uccb4\uc81c\uac00 \uc571 \ub370\uc774\ud130\ub97c \ubc31\uc5c5\uc5d0 \ud568\uaed8 \ub2f4\uc744 \uc218 \uc788\uc5b4\uc694.","\uc774 \ubc31\uc5c5\uc740 \uc560\ud50c\uc774\ub098 \uad6c\uae00\uc774 \uc5ec\ub7ec\ubd84\uc758 \uacc4\uc815\uc5d0\uc11c \uad00\ub9ac\ud558\ub294 \uac83\uc774\uace0, \uc6b0\ub9ac\uac00 \uadf8 \ub0b4\uc6a9\uc744 \ubcf4\uac70\ub098 \uac00\uc838\uc62c \uc218\ub294 \uc5c6\uc5b4\uc694.","\ubc31\uc5c5\uc5d0 \ub2f4\uae30\uc9c0 \uc54a\uac8c \ud558\ub824\uba74 \uae30\uae30 \uc124\uc815\uc5d0\uc11c \uc774 \uc571\uc758 \ubc31\uc5c5\uc744 \uaebc \uc8fc\uc138\uc694."],t.s)
B.aF7=new A.lh("4. \uae30\uae30 \uc790\ub3d9 \ubc31\uc5c5",B.agp)
B.akR=s(["\uc571\uc740 \uc2dc\ud5d8 \uc77c\uc815\uacfc \ud559\uc2b5 \uc790\ub8cc\ub97c \ucd5c\uc2e0\uc73c\ub85c \uc720\uc9c0\ud558\ub824\uace0 \uc815\ud574\uc9c4 \uc8fc\uc18c\uc5d0\uc11c \ubc84\uc804 \ubaa9\ub85d\uacfc \ubc14\ub010 \uc790\ub8cc\ub97c \ub0b4\ub824\ubc1b\uc544\uc694. \uc790\ub8cc\uc5d0\ub294 \ud55c\uc790\xb7\uc774\uc57c\uae30\xb7\uadf8\ub9bc\xb7\uc74c\uc131\uc774 \ud3ec\ud568\ub420 \uc218 \uc788\uc5b4\uc694. \ubc1b\uc740 \uc790\ub8cc\ub294 \uae30\uae30\uc5d0 \uc800\uc7a5\ud574 \uc778\ud130\ub137 \uc5c6\uc774\ub3c4 \uc4f8 \uc218 \uc788\uc5b4\uc694. \uc6f9\uc5d0\uc11c\ub294 \uc0c8 \ubc84\uc804\uc774 \ub098\uc654\ub294\uc9c0 \ud655\uc778\ud558\ub294 \ud30c\uc77c\ub3c4 \ud568\uaed8 \ud655\uc778\ud574\uc694.",'\uc774\ub54c \ubcf4\ub0b4\ub294 \uac74 "\uadf8 \ud30c\uc77c\uc744 \uc8fc\uc138\uc694"\ub77c\ub294 \uc694\uccad\ubfd0\uc774\uc5d0\uc694. \ud559\uc2b5 \uae30\ub85d\uc774\ub098 \uae30\uae30 \uc548\uc758 \uc815\ubcf4\ub294 \ud568\uaed8 \ubcf4\ub0b4\uc9c0 \uc54a\uc544\uc694.',"\ub2e4\ub9cc \uc778\ud130\ub137 \uc694\uccad\uc740 \uadf8 \ud30c\uc77c\uc744 \ubcf4\uad00\ud558\ub294 \ud638\uc2a4\ud305 \ud68c\uc0ac\uc758 \uc11c\ubc84\ub97c \uac70\uce58\uae30 \ub54c\ubb38\uc5d0, \uc811\uc18d \uc2dc\uac01\uacfc IP \uc8fc\uc18c \uac19\uc740 \uc811\uc18d \uae30\ub85d\uc774 \uadf8 \ud68c\uc0ac \ucabd\uc5d0 \uc7a0\uc2dc \ub0a8\uc744 \uc218 \uc788\uc5b4\uc694. \uc774 \uae30\ub85d\uc740 \uc6b0\ub9ac\uac00 \ub9cc\ub4e4\uc9c0\ub3c4 \ubcf4\uad00\ud558\uc9c0\ub3c4 \uc54a\uc544\uc694."],t.s)
B.aF8=new A.lh("5. \uc778\ud130\ub137\uc744 \uc4f0\ub294 \uc21c\uac04",B.akR)
B.amd=s(['"\uc790\ub791\ud558\uae30"\uc5d0\uc11c \ub9cc\ub4e0 \uae30\ub85d\uc99d \uc774\ubbf8\uc9c0\ub098 \ud559\uc2b5 \uae30\ub85d \ud30c\uc77c\uc740 \uc5ec\ub7ec\ubd84\uc774 \uc9c1\uc811 \ub0b4\ubcf4\ub0bc \ub54c\ub9cc \uae30\uae30 \ubc16\uc73c\ub85c \ub098\uac00\uc694.',"\ub0b4\ubcf4\ub0b4\uae30\ub97c \ub204\ub974\uba74 \uae30\uae30\uc758 \uacf5\uc720 \ucc3d\uc774 \uc5f4\ub9ac\uace0, \uac70\uae30\uc11c \uace0\ub978 \uc571(\uba54\uc2dc\uc9c0, \uc0ac\uc9c4\ucca9 \ub4f1)\uc73c\ub85c\ub9cc \uc804\ub2ec\ub3fc\uc694. \uc6b0\ub9ac \uc11c\ubc84\ub85c\ub294 \uc544\ubb34\uac83\ub3c4 \uac00\uc9c0 \uc54a\uc544\uc694.","\uae30\ub85d\uc99d \uc774\ubbf8\uc9c0\uc5d0\ub294 \uc774\ub984\uc774\ub098 \uc5f0\ub77d\ucc98\uac00 \ub4e4\uc5b4\uac00\uc9c0 \uc54a\uc544\uc694."],t.s)
B.aF5=new A.lh("6. \uae30\ub85d\uc744 \ub0b4\ubcf4\ub0bc \ub54c",B.amd)
B.ao2=s(["\ud559\uc2b5 \uae30\ub85d\uc740 \uc5ec\ub7ec\ubd84\uc774 \uc9c0\uc6b8 \ub54c\uae4c\uc9c0 \uae30\uae30\uc5d0 \ub0a8\uc544\uc694. \uc6b0\ub9ac\uac00 \ub530\ub85c \uc815\ud55c \ubcf4\uad00 \uae30\uac04\uc740 \uc5c6\uc5b4\uc694.","\uae30\ub85d\uc744 \uc9c0\uc6b0\ub824\uba74 \ub450 \uac00\uc9c0 \ubc29\ubc95\uc774 \uc788\uc5b4\uc694.",'\xb7 \uc124\uc815 \ud654\uba74\uc758 "\ud559\uc2b5 \uae30\ub85d"\uc5d0\uc11c \uae30\ub85d \ucd08\uae30\ud654\ub97c \ub204\ub974\uba74 \ud559\uc2b5 \uae30\ub85d\uc774 \uc9c0\uc6cc\uc838\uc694.',"\xb7 \uc571\uc744 \uc0ad\uc81c\ud558\uba74 \uc571\uc774 \ub9cc\ub4e0 \ub370\uc774\ud130\uac00 \uae30\uae30\uc5d0\uc11c \ud568\uaed8 \uc0ac\ub77c\uc838\uc694.","\uae30\uae30 \uc790\ub3d9 \ubc31\uc5c5\uc5d0 \uc774\ubbf8 \ub2f4\uae34 \ub0b4\uc6a9\uc740 \uae30\uae30 \uc124\uc815\uc758 \ubc31\uc5c5 \uad00\ub9ac\uc5d0\uc11c \uc9c0\uc6cc \uc8fc\uc138\uc694."],t.s)
B.aF2=new A.lh("7. \ubcf4\uad00 \uae30\uac04\uacfc \uc9c0\uc6b0\ub294 \ubc29\ubc95",B.ao2)
B.aco=s(["\uc774 \uc571\uc740 \ucd08\ub4f1\ud559\uc0dd\uacfc \uc911\ud559\uc0dd\uc774 \ud55c\uc790\ub97c \uacf5\ubd80\ud558\ub3c4\ub85d \ub9cc\ub4e4\uc5c8\uc5b4\uc694. \uac1c\uc778\uc815\ubcf4\ub97c \ubaa8\uc73c\uc9c0 \uc54a\uc73c\ub2c8 \uac00\uc785\ud560 \ub54c \ubcf4\ud638\uc790 \ub3d9\uc758\ub97c \ubc1b\ub294 \uc808\ucc28\ub3c4 \uc5c6\uc5b4\uc694. \uc5f0\uad6c \ucc38\uc5ec\ub294 \uc608\uc678\uc608\uc694. \ubaa8\uc9d1\ud560 \ub54c \ubcf4\ud638\uc790 \ub3d9\uc758\ub97c \uba3c\uc800 \ubc1b\uc544\uc694(9\uc808).","\ubcf4\ud638\uc790\uaed8\uc11c\ub294 \uc790\ub140\uc758 \uae30\uae30\uc5d0\uc11c \uc571 \uc124\uc815\uacfc \ud559\uc2b5 \uae30\ub85d\uc744 \uc9c1\uc811 \ud655\uc778\ud558\uace0 \uc9c0\uc6b8 \uc218 \uc788\uc5b4\uc694.","\ub098\uc911\uc5d0 \uacc4\uc815\uc774\ub098 \ub3d9\uae30\ud654 \uae30\ub2a5\uc774 \uc0dd\uaca8\uc11c \uac1c\uc778\uc815\ubcf4\ub97c \ub2e4\ub8e8\uac8c \ub418\uba74, \uadf8\ub54c\ub294 \ubc95\uc5d0 \ub530\ub77c \ubcf4\ud638\uc790 \ub3d9\uc758\ub97c \uba3c\uc800 \ubc1b\uace0 \uc774 \ubc29\uce68\ub3c4 \ubbf8\ub9ac \uace0\uccd0\uc11c \uc54c\ub824 \ub4dc\ub9b4\uac8c\uc694."],t.s)
B.aFa=new A.lh("8. \ub9cc 14\uc138 \ubbf8\ub9cc \uc5b4\ub9b0\uc774\uc640 \ubcf4\ud638\uc790\uc5d0\uac8c",B.aco)
B.akt=s(["\uc571\uc744 \ub354 \uc88b\uac8c \ub9cc\ub4e4\ub824\uace0, \uc6b4\uc601\uc790\uac00 \ubbf8\ub9ac \ubaa8\uc9d1\ud55c \ucc38\uc5ec\uc790\uc5d0\uac8c\uc11c\ub9cc \ud559\uc2b5 \ud69f\uc218\ub97c \ubaa8\uc740 \ud30c\uc77c\uc744 \ubc1b\uc544\uc694. \ucc38\uc5ec\ub294 \uc120\ud0dd\uc774\uace0, \ucc38\uc5ec\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc571\uc758 \ubaa8\ub4e0 \uae30\ub2a5\uc744 \uadf8\ub300\ub85c \uc4f8 \uc218 \uc788\uc5b4\uc694.",'\ub9cc 14\uc138 \ubbf8\ub9cc \ucc38\uc5ec\uc790\ub294 \ubaa8\uc9d1\ud560 \ub54c \ubcf4\ud638\uc790(\ubc95\uc815\ub300\ub9ac\uc778)\uc5d0\uac8c \uba3c\uc800 \ub3d9\uc758\ub97c \ubc1b\uc544\uc694. \uc571\ub3c4 \ud30c\uc77c\uc744 \ubcf4\ub0b4\uae30 \uc804\uc5d0 "\ubcf4\ud638\uc790 \ub3d9\uc758\ub97c \ubc1b\uc740 \ucc38\uc5ec\uc790\ub9cc" \ubcf4\ub0b4 \ub2ec\ub77c\uace0 \ud55c \ubc88 \ub354 \uc54c\ub824\uc694.',"\ud30c\uc77c\uc5d0 \ub2f4\uae30\ub294 \uac83\uc740 \uc6b4\uc601\uc790\uac00 \ub098\ub220 \uc900 \ucc38\uc5ec \ucf54\ub4dc, \ubaa9\ud45c \uae09\uc218, \uccab \ud559\uc2b5\uc77c\ubd80\ud130 \uba70\uce60\uc9f8\uc778\uc9c0\ub97c \uc13c \ub0a0\uc9dc \ubc88\ud638\uc640 \uadf8\ub0a0\uc758 \ud559\uc2b5 \uc2dc\uc791\xb7\uc644\ub8cc \uac19\uc740 \ub3d9\uc791 \ud69f\uc218, \uae09\uc218\ub97c \uc644\uc131\ud558\uac70\ub098 \ubaa8\uc758\uc2dc\ud5d8\uc5d0 \ucc98\uc74c \ud569\uaca9\ud55c \ub0a0\uacfc \ud30c\uc77c\uc744 \ub9cc\ub4e0 \ub0a0\uc758 \ub0a0\uc9dc \ubc88\ud638, \uce90\ub9ad\ud130 \ud45c\uc2dc \uc2e4\ud5d8 \ubc30\uc815\uac12(\ucf1c\uc9d0/\uaebc\uc9d0)\ubfd0\uc774\uc5d0\uc694. \uc2e4\uc81c \ub0a0\uc9dc\uc640 \uc2dc\uac01, \ub2f5\uc548, \ud55c\uc790\ubcc4 \uae30\ub85d, \uc774\ub984\uacfc \uc5f0\ub77d\ucc98, \uae30\uae30 \uc2dd\ubcc4\uac12\uc740 \ub2f4\uae30\uc9c0 \uc54a\uc544\uc694.",'\ud30c\uc77c\uc740 \uc124\uc815 \ud654\uba74\uc758 "\ud559\uc2b5 \uae30\ub85d \u2192 \uc5f0\uad6c \ucc38\uc5ec"\uc5d0\uc11c \uc9c1\uc811 \uacf5\uc720 \ucc3d\uc744 \uc5f4\uc5b4 \ubcf4\ub0bc \ub54c\ub9cc \uae30\uae30 \ubc16\uc73c\ub85c \ub098\uac00\uc694. \uc571\uc774 \uc800\uc808\ub85c \ubcf4\ub0b4\ub294 \uc77c\uc740 \uc5c6\uc5b4\uc694.','\ucc38\uc5ec \ucf54\ub4dc\ub294 \uae30\uae30 \uc548\uc5d0\ub9cc \uc800\uc7a5\ub418\uace0 \ud559\uc2b5 \uae30\ub85d \ubc31\uc5c5 \ud30c\uc77c\uc5d0\ub294 \ub4e4\uc5b4\uac00\uc9c0 \uc54a\uc544\uc694. "\uc5f0\uad6c \ucc38\uc5ec"\uc5d0\uc11c \uc9c0\uc6b0\uac70\ub098 \ud559\uc2b5 \uae30\ub85d\uc744 \ucd08\uae30\ud654\ud558\uba74 \ud568\uaed8 \uc9c0\uc6cc\uc838\uc694. \ubaa8\uc9d1\ud560 \ub54c \ubc1b\uc740 \uc5f0\ub77d\ucc98\ub294 \uc9d1\uacc4 \ud30c\uc77c\uacfc \ub530\ub85c \ubcf4\uad00\ud574\uc694. \ucc38\uc5ec \ucf54\ub4dc\uc640 \uc5f0\ub77d\ucc98\ub97c \uc787\ub294 \uba85\ub2e8\uc740 \uc6b4\uc601\uc790\ub9cc \ubd10\uc694. \uce90\ub9ad\ud130 \ud45c\uc2dc \uc2e4\ud5d8 \ubc30\uc815\uac12(\ucf1c\uc9d0/\uaebc\uc9d0)\uc740 \ucc38\uc5ec \ucf54\ub4dc\ub97c \uc9c0\uc6b0\uac70\ub098 \ud559\uc2b5 \uae30\ub85d\uc744 \ucd08\uae30\ud654\ud574\ub3c4 \uae30\uae30\uc5d0 \ub0a8\uc544\uc11c, \uac19\uc740 \ucf54\ub4dc\ub97c \ub2e4\uc2dc \ub123\uc73c\uba74 \uc6d0\ub798 \ubc30\uc815\uc73c\ub85c \ub3cc\uc544\uac00\uc694.',"\ubcf4\uad00 \uae30\uac04: \uc9d1\uacc4 \ud30c\uc77c\uc740 \uc5f0\uad6c\uac00 \ub05d\ub09c \ub4a4 1\ub144 \uc548\uc5d0 \uc9c0\uc6cc\uc694. \uc5f0\ub77d\ucc98\uc640 \ucc38\uc5ec \ucf54\ub4dc \uba85\ub2e8\uc740 \uc5f0\uad6c\uac00 \ub05d\ub098\uba74 \ubc14\ub85c \uc9c0\uc6cc\uc694. \ucc38\uc5ec\ub97c \uadf8\ub9cc\ub450\uac70\ub098 \ubcf4\ub0b8 \ud30c\uc77c\uc744 \uc9c0\uc6cc \ub2ec\ub77c\uace0 \ud558\ub824\uba74 \ucc38\uc5ec \ucf54\ub4dc\uc640 \ud568\uaed8 \uc544\ub798 \ubb38\uc758\ucc98\ub85c \uc54c\ub824 \uc8fc\uc138\uc694."],t.s)
